    el.style.pointerEvents = 'none';
    el.remove();
  }
  // Check if bouncex or any other modal exists
  const bx = document.querySelectorAll('[class*="bx-"], #bx-campaign-2125258');
  bx.forEach(b => {
    b.style.display = 'none';
    b.style.pointerEvents = 'none';
  });
  return {
    removed: !!el,
    bxCount: bx.length
  };
});
